          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-04 synthetic strictly. Frequent changes are critical for turbo bearing life and VANOS health.", parts: ["5.25L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
          ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently, especially if the 220i is tuned to Stage 1 power levels.", parts: ["4x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["4x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "160 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "Physically clean carbon buildup from intake valves. Completely restores lost airflow and cures rough idle.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "PCV Valve Inspection", details: "Check the valve cover for whistling noises. Replace the diaphragm to prevent vacuum leaks and oil consumption.", parts: ["PCV Diaphragm"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" } ],
          preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Serpentine Belt & Tensioner", details: "Replace to prevent belt snapping.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ],
          coolingAndHvac: [ { interval: "60,000 km", timeLimit: "4 years", task: "Coolant Vent Line Upgrade", details: "CRITICAL: Proactively replace the brittle plastic coolant return line with a reinforced silicone hose to prevent sudden overheating.", parts: ["Silicone Hose"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "40 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.2L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Water Pump & Heat Module Check", details: "Inspect the plastic housing for micro-cracks and weeping coolant.", parts: ["Water Pump Unit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" } ],
          engineMechanical: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Aluminum Charge Pipe Install", details: "CRITICAL: Do not flash the ECU without replacing the plastic charge pipe.", parts: ["Aluminum Pipe"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "180 EUR" }, { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The B48 chain is incredibly robust. Listen for cold start rattling at extreme high mileage.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ]
