        engineeringData: { blockDesign: "Open-deck Aluminum alloy block with cast-iron cylinder liners. Mounted longitudinally in the F22 chassis for perfect 50:50 weight distribution and Rear-Wheel Drive dynamics.", crankshaft: "Cast Iron, supported by 5 main bearings, utilizing balance shafts to reduce inherent 4-cylinder vibrations.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "170A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy tailored for direct injection. Features a lower 10.0:1 compression ratio compared to the 220i's 11.0:1, making it vastly superior for tuning and forced induction.", wristPinDiameter: "22 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design for 10.0:1 compression.", intakePortFlow: "High-velocity tumble ports. Features BMW's Valvetronic system to control intake valve lift directly, eliminating throttle body pumping losses.", valveSizes: "Intake: 32.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, plus continuous Valvetronic.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "Direct injection ports bypass the intake valves, leading to inevitable carbon buildup." }, oilAndCooling: { oilSquirters: "Yes, dedicated under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump. Chain-driven (infamous for failure on early models).", thermostatOpening: "108°C Electronic map-controlled.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "High-Pressure Direct Injection (HPI).", maxPressure: "200 Bar.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "450 Nm.", maxSafePowerStock: "330 hp.", maxSafeRPM: "6800 RPM.", weakestLink: "Timing Chain, Connecting Rods (under low RPM torque spikes), Plastic Charge Pipe." }, electrical: { coils: "Push-down 3-wire Active Coils.", ecu: "Bosch MEVD17.2.9." } },
        recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan of the N20 engine.", parts: [ { category: "Timing Chain Kit", brand: "Genuine BMW", note: "CRITICAL: Proactive replacement with the revised guides prevents catastrophic engine failure." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Mandatory upgrade before applying any ECU tunes to prevent shattering." }, { category: "Electric Water Pump", brand: "Pierburg / VDO", note: "Replace proactively every 100k km before sudden failure." }, { category: "Oil Filter Housing Gasket", brand: "Elring", note: "CRITICAL: Stops catastrophic oil leaks onto the serpentine belt." }, { category: "Valve Cover Assembly", brand: "Elring / Genuine BMW", note: "Must replace entire cover to fix torn internal PCV diaphragms." }, { category: "Spark Plugs", brand: "NGK Laser Iridium", note: "Must gap tighter if running Stage 1/2 software." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Upgrade to latest revisions to prevent boost misfires." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use exclusively OEM quality to protect the delicate VANOS system." } ] },
