          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-01 synthetic strictly. The N20 requires pristine oil to protect the fragile timing chain and turbo bearings.", parts: ["5.0L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
          ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently, especially if the 228i is tuned.", parts: ["4x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "70 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["4x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "160 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Walnut Blasting Carbon Clean", details: "CRITICAL: Physically clean carbon buildup from intake valves. Completely restores lost airflow and smooths idle.", parts: ["Intake Gaskets", "Walnut Media"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "350 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Valve Cover Assembly", details: "Replace entire plastic valve cover due to failing internal PCV valve causing massive oil consumption.", parts: ["Valve Cover", "Alu Bolts"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" } ],
          preventiveAndSuspension: [ { interval: "80,000 km", timeLimit: "6 years", task: "Oil Filter Housing Gasket", details: "CRITICAL: Proactively replace to prevent massive oil leaks onto the serpentine belt. MUST PRIME OIL SYSTEM AFTERWARD.", parts: ["Gaskets", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Serpentine Belt & Tensioner", details: "Replace to prevent belt snapping.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" } ],
          coolingAndHvac: [ { interval: "100,000 km", timeLimit: "7 years", task: "Electric Water Pump & T-Stat", details: "CRITICAL: Proactive replacement before sudden failure leaves you stranded.", parts: ["Pierburg Pump", "Thermostat", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "550 EUR" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["7.0L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R134a.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 EUR" } ],
