          oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-01 synthetic strictly. The N26 requires pristine oil to protect the fragile timing chain and turbo bearings.", parts: ["5.0L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
