  engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The TU2 update (B38A15P) introduces the Miller-cycle combustion process for extreme fuel efficiency. Mounted Transversely specifically for the Front-Wheel Drive architecture of the U06 Active Tourer.", crankshaft: "Forged Steel, supported by 4 main bearings, providing excellent durability for a small displacement engine.", pistonSpeed: "14.2 m/s @ 6000 RPM.", alternator: "150A Valeo.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy meticulously tailored for the Miller-cycle combustion profile.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M8 stretch bolts.", crankMainJournal: "50.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Optimized pent-roof design tailored for the Miller-cycle.", intakePortFlow: "Features BMW's 4th Generation Valvetronic system integrated directly into the cylinder head, alongside the massive addition of Low-Pressure Port Injectors in the manifold to complement the Direct Injectors.", valveSizes: "Intake: 30.0 mm / Exhaust: 28.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Double VANOS on both intake and exhaust, heavily modified mapping for Miller-cycle valve timing.", lifterType: "Hydraulic lifters with intermediate levers.", specialFeature: "Dual Fuel Injection (Port + Direct) entirely eliminates intake valve carbon buildup, a historic issue for BMW direct-injection engines." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "105°C Electronic map-controlled Heat Management Module.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "Dual Injection (High-Pressure Direct + Low-Pressure Port).", maxPressure: "350 Bar (Direct) / 5 Bar (Port).", injectors: "3x Direct Solenoid Injectors + 3x Port Injectors." }, tuningLimits: { maxSafeTorqueStock: "320 Nm.", maxSafePowerStock: "190 hp.", maxSafeRPM: "6500 RPM.", weakestLink: "Plastic Charge Pipe, Fluid-Filled Engine Mounts, OPF Backpressure, Factory Turbocharger airflow limits." }, electrical: { coils: "Push-down 3-wire Active Coils (Redesigned for TU2).", ecu: "Bosch MG1CS201." } },
  recommendedParts: { description: "Crucial preventative maintenance parts to maximize the lifespan and reliability of the transverse B38 TU2 engine.", parts: [ { category: "Water Pump Assembly", brand: "Genuine BMW / INA", note: "CRITICAL: Plastic housing cracks over time; replace proactively if weeping coolant is detected." }, { category: "Spark Plugs", brand: "NGK Laser Iridium", note: "Must be replaced strictly every 40k km on tuned engines to prevent severe misfires." }, { category: "Ignition Coils", brand: "Eldor / Bosch", note: "Upgrade to the latest TU2 revisions to prevent high-RPM boost misfires." }, { category: "Engine Mounts", brand: "Corteco / Genuine BMW", note: "Fluid-filled mounts fail incredibly rapidly under the aggressive vibration of the 3-cylinder engine." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "Mandatory upgrade before applying any ECU tunes to prevent shattering under boost." }, { category: "Port Fuel Injectors", brand: "Bosch", note: "Proactive replacement if low-load hesitation occurs due to port injection clogging." }, { category: "Serpentine Belt", brand: "Continental", note: "Replace immediately if squeaking or showing visual signs of cracking." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Use exclusively OEM quality to protect the delicate VANOS system and timing chain." } ] },
