    fluidsAndDrivetrain: [ { interval: "60,000 km", timeLimit: "5 years", task: "7-Speed DCT Service", details: "Drain fluid, replace internal filters and pan gasket, and refill Pentosin FFL-4.", parts: ["6.0L Pentosin FFL-4", "DCT Filter Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" }, { interval: "80,000 km", timeLimit: "6 years", task: "Front Differential Oil", details: "Extract and refill the transverse front differential.", parts: ["0.8L 75W-90 GL-5"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" }, { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Flush DOT 4 Low Viscosity fluid.", parts: ["1.0L DOT 4 LV"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "8 years", task: "DCT Mechatronic Fluid", details: "Flush the dedicated hydraulic fluid for the DCT clutch actuation unit.", parts: ["1.0L Pentosin CHF 11S"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "90 EUR" } ],
    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-12 FE synthetic strictly. Frequent changes are critical for turbo bearing life and VANOS health.", parts: ["4.25L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Integrated in tank; replace if fuel pressure drops.", parts: ["Filter Unit"], importance: "Low", laborDifficulty: "Advanced", estimatedCost: "120 EUR" } ],
    ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently, especially if the 218i is tuned to higher output.", parts: ["3x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["3x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Engine Mount Inspection", details: "Check fluid-filled mounts for weeping or collapse. The transverse 3-cylinder vibrations destroy them rapidly.", parts: ["Engine Mounts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Port Injector Cleaning", details: "Due to the dual injection setup, carbon blasting is no longer needed, but running injector cleaner through the port injectors maintains optimal spray patterns.", parts: ["Fuel Additive"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" } ],
    preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Serpentine Belt & Tensioner", details: "Replace to prevent belt snapping.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "PCV Valve Inspection", details: "Listen for whistling from the valve cover, indicating a torn diaphragm.", parts: ["PCV Diaphragm"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Rear Trailing Arm Bushings", details: "Inspect and replace rear suspension bushings to prevent wandering under load.", parts: ["Bushings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "180 EUR" } ],
