    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "BMW Longlife-12 FE synthetic strictly. Frequent changes are critical for turbo bearing life and VANOS health.", parts: ["4.25L Oil", "Mann-Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "80 EUR" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace paper element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "1 year", task: "Cabin Filter", details: "Activated carbon replacement.", parts: ["Cabin Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Fuel Filter", details: "Integrated in tank; replace if fuel pressure drops.", parts: ["Filter Unit"], importance: "Low", laborDifficulty: "Advanced", estimatedCost: "120 EUR" } ],
    ignitionAndEngine: [ { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plugs", details: "Replace frequently, especially if the 220i is tuned to higher output.", parts: ["3x NGK Plugs"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "60,000 km", timeLimit: "5 years", task: "Ignition Coils", details: "Proactive replacement of degrading coil packs to prevent boost misfires.", parts: ["3x Eldor Coils"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Engine Mount Inspection", details: "Check fluid-filled mounts for weeping or collapse. The transverse 3-cylinder vibrations destroy them rapidly.", parts: ["Engine Mounts"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Port Injector Cleaning", details: "Due to the dual injection setup, carbon blasting is no longer needed, but running injector cleaner through the port injectors maintains optimal spray patterns.", parts: ["Fuel Additive"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 EUR" } ],
    preventiveAndSuspension: [ { interval: "100,000 km", timeLimit: "6 years", task: "Front Control Arm Bushings", details: "Replace fluid-filled thrust arm bushings if leaking or torn.", parts: ["Bushings"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "140 EUR" }, { interval: "80,000 km", timeLimit: "5 years", task: "Serpentine Belt & Tensioner", details: "Replace to prevent belt snapping.", parts: ["Belt", "Tensioner"], importance: "High", laborDifficulty: "Easy", estimatedCost: "120 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "PCV Valve Inspection", details: "Listen for whistling from the valve cover, indicating a torn diaphragm.", parts: ["PCV Diaphragm"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Rear Trailing Arm Bushings", details: "Inspect and replace rear suspension bushings to prevent wandering under load.", parts: ["Bushings"], importance: "Medium", laborDifficulty: "Advanced", estimatedCost: "180 EUR" } ],
    coolingAndHvac: [ { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush", details: "Drain and refill G48 coolant.", parts: ["6.5L G48"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 EUR" }, { interval: "100,000 km", timeLimit: "6 years", task: "Water Pump Assembly Replacement", details: "Proactively replace the plastic water pump housing before it cracks and dumps coolant.", parts: ["Water Pump", "Alu Bolts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" }, { interval: "4 Years", timeLimit: "4 years", task: "A/C Recharge", details: "Evacuate and recharge R1234yf system.", parts: ["Refrigerant"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" }, { interval: "150,000 km", timeLimit: "10 years", task: "Heat Management Module", details: "Inspect the electronic water valving module for leaks.", parts: ["Thermostat Unit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" } ],
    engineMechanical: [ { interval: "Immediately", timeLimit: "Unlimited", task: "Aluminum Charge Pipe Install", details: "CRITICAL: Do not flash the ECU without replacing the plastic charge pipe.", parts: ["Aluminum Pipe"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "180 EUR" }, { interval: "250,000 km", timeLimit: "Unlimited", task: "Timing Chain Inspection", details: "The B38 chain is incredibly robust. Listen for cold start rattling at extreme high mileage.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Oil Filter Housing Gasket", details: "Replace rubber profile gaskets if oil is weeping down the front of the block.", parts: ["Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" }, { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Actuator Calibration", details: "Run ISTA diagnostic routines to re-learn Valvetronic limit stops.", parts: ["Diagnostic"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "0 EUR" } ]
