  engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with wire-arc sprayed iron cylinder linings. The 'C' in B47C20B denotes transverse mounting for the Front-Wheel Drive U06 Active Tourer platform. Part of the highly successful modular B-series family, featuring acoustic dampening to reduce diesel clatter significantly.", crankshaft: "Forged Steel, supported by 5 main bearings, highly robust.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "48V Integrated Starter-Generator (Replaces traditional alternator).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with internal oil cooling galleries and a specialized combustion bowl in the crown.", wristPinDiameter: "26 mm.", connectingRodLength: "144 mm.", rodBoltSize: "M9 stretch bolts.", crankMainJournal: "55.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.66." }, cylinderHead: { combustionChamberVol: "Flat head design; combustion occurs entirely within the piston bowl.", intakePortFlow: "16-valve DOHC. Features highly efficient EGR routing integrated into the head and swirl flaps in the manifold.", valveSizes: "Intake: 27.2 mm / Exhaust: 24.6 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed timing.", lifterType: "Hydraulic lifters with low-friction roller rockers.", specialFeature: "The timing chain is mounted at the REAR of the engine to save space, improving packaging for the transverse FWD layout." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Map-controlled variable volume gear pump.", thermostatOpening: "88°C Mechanical.", oilCooler: "Water-to-oil heat exchanger attached to the filter housing." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2000 Bar (CP4.1 Pump).", injectors: "4x Solenoid Injectors (Highly reliable)." }, tuningLimits: { maxSafeTorqueStock: "500 Nm.", maxSafePowerStock: "260 hp.", maxSafeRPM: "4800 RPM.", weakestLink: "High-Pressure Fuel Pump (under poor lubrication), 7-Speed DCT torque limit, OPF/DPF Backpressure." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch MD1CS001." } },
